def write(path):
    cols=['source','source_key','url','tos_url','robots_url','retrieved_at','clauses','classification','notes','evidence_files']
    with open(path,'w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=cols); w.writeheader()
        for s in S: w.writerow({**s,'retrieved_at':RT})
CLASS={s['source_key']:s['classification'] for s in S}
if __name__=='__main__': write('/workspace/audit/odds/source_permissions_audit.csv'); print(CLASS)
